import javax.inject.Inject

// The sync core (packages/sync-core, TypeScript) run on the phone in an embedded JS engine, so the phone
// applies the operation log with the same rules as the web app, the desktop app and the instance.
// src/main/assets/sync-core.js is generated by packages/sync-core/scripts/android-assets.ts (committed).
plugins {
    alias(libs.plugins.android.library)
    alias(libs.plugins.kotlin.android)
}

android {
    namespace = "io.github.magiszonekk.discordrive.syncjs"
    compileSdk = 35

    defaultConfig {
        minSdk = 29
        testInstrumentationRunner = "androidx.test.runner.AndroidJUnitRunner"
    }

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }
    kotlinOptions {
        jvmTarget = "17"
    }
}

dependencies {
    implementation(libs.quickjs.android)
    implementation(libs.javascriptengine)

    androidTestImplementation(libs.androidx.test.runner)
    androidTestImplementation(libs.androidx.test.junit)
    androidTestImplementation(libs.junit4)
}

/**
 * Compatibility vectors for the on-device test: random operation logs from the sync-core simulator and the
 * SHA-256 of the state Node reaches with each. Generated at build time (Node + the repository's npm
 * dependencies), not committed. Override the command with -PsyncVectorsNpx=/path/to/npx.
 */
abstract class GenerateSyncVectors @Inject constructor(private val exec: ExecOperations) : DefaultTask() {
    @get:InputDirectory
    abstract val syncCoreDir: DirectoryProperty

    @get:Input
    abstract val npx: Property<String>

    @get:OutputDirectory
    abstract val outputDir: DirectoryProperty

    @TaskAction
    fun run() {
        val out = outputDir.get().asFile.resolve("sync-vectors.txt")
        exec.exec {
            workingDir = syncCoreDir.get().asFile
            commandLine(npx.get(), "tsx", "scripts/android-assets.ts", "--vectors", out.absolutePath, "--vectors-only")
        }
    }
}

val generateSyncVectors = tasks.register<GenerateSyncVectors>("generateSyncVectors") {
    syncCoreDir.set(rootProject.layout.projectDirectory.dir("../../packages/sync-core"))
    npx.set(providers.gradleProperty("syncVectorsNpx").orElse("npx"))
    outputDir.set(layout.buildDirectory.dir("generated/syncVectors"))
}

androidComponents {
    onVariants { variant ->
        variant.androidTest?.sources?.assets?.addGeneratedSourceDirectory(generateSyncVectors, GenerateSyncVectors::outputDir)
    }
}
